{"tool_call_id": "32", "tool_name": "write", "parameters": {"content": "import { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { crmApi as api, type ClientComplaint, type ClientComplaintListResponse } from "@/lib/crmApi";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { ArrowLeft, ArrowRight, Search, CheckCircle, XCircle, AlertTriangle, Clock, XCircle as XCircleIcon } from "lucide-react";
import { type ClientType } from "@/types/crm";

interface ClientComplaintListProps {
  clientType: ClientType;
  clientTypeLabel: string;
  listKey: string;
}

export function ClientComplaintList({ clientType, clientTypeLabel, listKey }: ClientComplaintListProps) {
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const pageSize = 20;

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(search), 300);
    return () => clearTimeout(timer);
  }, [search]);

  const { data, isLoading } = useQuery({
    queryKey: [listKey, page, debouncedSearch],
    queryFn: () => api.listClientComplaints(clientType, { page, page_size: pageSize, q: debouncedSearch }),
  });

  const complaints = data?.items ?? [];
  const total = data?.total ?? 0;
  const totalPages = Math.ceil(total / pageSize);

  const getColumns = () => {
    switch (clientType) {
      case "client-feedback":
        return [
          { key: "feedback_id", label: "Feedback ID" },
          { key: "date", label: "Date" },
          { key: "client_name", label: "Client" },
          { key: "reference_type", label: "Reference Type" },
          { key: "overall_rating", label: "Overall Rating" },
          { key: "would_recommend", label: "Would Recommend" },
        ];
      case "client-complaint":
        return [
          { key: "complaint_id", label: "Complaint ID" },
          { key: "date_raised", label: "Date Raised" },
          { key: "client_name", label: "Client" },
          { key: "complaint_type", label: "Complaint Type" },
          { key: "severity", label: "Severity" },
          { key: "status", label: "Status" },
        ];
      default:
        return [];
    }
  };

  const columns = getColumns();

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "Open": return <AlertTriangle className="h-4 w-4 text-yellow-500" />;
      case "Investigating": return <Clock className="h-4 w-4 text-blue-500" />;
      case "Resolved": return <CheckCircle className="h-4 w-4 text-green-500" />;
      case "Closed": return <CheckCircle className="h-4 w-4 text-gray-500" />;
      case "Rejected": return <XCircleIcon className="h-4 w-4 text-red-500" />;
      default: return null;
    }
  };

  const getSeverityIcon = (severity: string) => {
    switch (severity) {
      case "Low": return <AlertTriangle className="h-4 w-4 text-green-500" />;
      case "Medium": return <AlertTriangle className="h-4 w-4 text-yellow-500" />;
      case "High": return <AlertTriangle className="h-4 w-4 text-orange-500" />;
      case "Critical": return <XCircleIcon className="h-4 w-4 text-red-500" />;
      default: return null;
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">{clientTypeLabel}</h1>
        <Button asChild>
          <Link to={`/${clientType}/new`}>New {clientTypeLabel}</Link>
        </Button>
      </div>

      <Card>
        <CardContent className="pt-6">
          <div className="relative mb-4">
            <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder={`Search ${clientTypeLabel.toLowerCase()}...`}
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-10"
            />
          </div>

          <div className="rounded-md border">
            <Table>
              <TableHeader>
                <TableRow>
                  {columns.map((col) => (
                    <TableHead key={col.key}>{col.label}</TableHead>
                  ))}
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {isLoading ? (
                  <TableRow>
                    <TableCell colSpan={columns.length + 1} className="text-center">Loading...</TableCell>
                  </TableRow>
                ) : complaints.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={columns.length + 1} className="text-center">No {clientTypeLabel.toLowerCase()} found</TableCell>
                  </TableRow>
                ) : (
                  complaints.map((item) => (
                    <TableRow key={item.id}>
                      {columns.map((col) => (
                        <TableCell key={col.key}>
                          {col.key === "would_recommend" ? (
                            item.would_recommend !== null ? (
                              item.would_recommend ? <CheckCircle className="h-4 w-4 text-green-500" /> : <XCircle className="h-4 w-4 text-red-500" />
                            ) : "—"
                          ) : col.key === "overall_rating" ? (
                            <div className="flex items-center gap-1">
                              <span>{item.overall_rating}</span>
                              <span className="text-yellow-500">★</span>
                            </div>
                          ) : col.key === "date" || col.key === "date_raised" ? (
                            new Date(item[col.key as keyof typeof item] as string).toLocaleDateString()
                          ) : col.key === "client_name" ? (
                            item.client_name
                          ) : col.key === "status" ? (
                            <div className="flex items-center gap-1">
                              {getStatusIcon(item.status)}
                              <span>{item.status}</span>
                            </div>
                          ) : col.key === "severity" ? (
                            <div className="flex items-center gap-1">
                              {getSeverityIcon(item.severity)}
                              <span>{item.severity}</span>
                            </div>
                          ) : (
                            String(item[col.key as keyof typeof item] || "-")
                          )}
                        </TableCell>
                      ))}
                      <TableCell>
                        <Button variant="ghost" asChild>
                          <Link to={`/${clientType}/${item.id}`}>View</Link>
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>

          <div className="flex items-center justify-between mt-4">
            <span className="text-sm text-muted-foreground">
              {total} {clientTypeLabel.toLowerCase()}{total !== 1 ? "s" : ""}
            </span>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={page === 1}
              >
                <ArrowLeft className="h-4 w-4" />
              </Button>
              <span className="text-sm">Page {page} of {totalPages}</span>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                disabled={page >= totalPages}
              >
                <ArrowRight className="h-4 w-4" />
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}
